STRINGS.SCRAPBOOK.SPECIALINFO.PLANTBOOSTER_GROWTH = "Можна використати для удобрення та миттєвого вирощення рослин, що не належать до фермерських культур..\n\nВони не накопичуються та замінюють інші використані добрива.\n\nБустер прибирається якщо грядку викопати."
STRINGS.SCRAPBOOK.SPECIALINFO.PLANTBOOSTER_VITALITY = "Можна використати для удобрення та миттєвого вирощення будь-яких рослин.\n\nПри використанні на звичайних рослинах:\n\nНе потребує добрива та захищає від цілей.\n\nПри використанні на фермерських культурах:\n\nПросувається на один етап росту і захищає від цілей.\n\nВони не накопичуються та замінюють інші використані добрива.\n\nБустер прибирається якщо грядку викопати."
STRINGS.SCRAPBOOK.SPECIALINFO.PLANTBOOSTER_YIELD = "Можна використати для удобрення та миттєвого вирощення будь-яких рослин.\n\nПри використанні на звичайних рослинах:\n\nДодає більше продукції коли повністю виросте.\n\nПри використанні на фермерських культурах:\n\nПросувається на один етап, додає більше продукції.\n\nВони не накопичуються та замінюють інші використані добрива.\n\nБустер прибирається якщо грядку викопати."
STRINGS.SCRAPBOOK.SPECIALINFO.PLANTBOOSTER_SUPERGROWTH = "Можна використати для удобрення та миттєвого вирощення будь-яких рослин.\n\nПри використанні на фермерських культурах:\n\nПовністю вирощує рослину та має 25% шанс зробити її гігантською.\n\nВони не накопичуються та замінюють інші використані добрива.\n\nБустер прибирається якщо грядку викопати."
STRINGS.SCRAPBOOK.SPECIALINFO.PIGCOIN = "Головна валюта звичайного пересічного свина."
STRINGS.SCRAPBOOK.SPECIALINFO.SEEDSBAG = "Контейнер з 4 слотами для насіння.\n\nПсування сповільнюється на 60%.\n\nВ подальшому може бути розширений Еласторозпіркою для покращення його можливостей щодо зберігання та консервування.\n\nОлівець-перо можна використати на ньому, для нанесення назви насіння."
STRINGS.SCRAPBOOK.SPECIALINFO.FOODAMMO_TOMATO = "Сповільнює наземних цілей на 5 seconds."
STRINGS.SCRAPBOOK.SPECIALINFO.SPICEPACK_REWORK = "Контейнер з 6 слотами для їжі та інгредієнтів.\n\nСповільнює псування продукції."
STRINGS.SCRAPBOOK.SPECIALINFO.PIGGYBANK = "Контейнер з 6 слотами для валюти.\n\nВ подальшому може бути розширений Еласторозпіркою."
STRINGS.SCRAPBOOK.SPECIALINFO.WX78MODULE_GOURMAND = "Підключається до плати схеми Бета WX-78. Скануйте старого Свина, або будь-яку іншу Істоту.\n\nПотребує 2 сокети, підвищує позитивні характеристики та знижує шкоду від їжі на 5 одиниць.\n\nЛагодження бета-модулів II покращує цей модуль: він збільшує позитивні та зменшує негативні характеристики на 5 одиниць, а також дозволяє WX-78 швидко поглинати їжу."
STRINGS.SCRAPBOOK.SPECIALINFO.WX78MODULE_COOKER = "Підключається до плати схеми Бета WX-78. Скануйте Личинку або Надмилу Личинку для отримання рецепта.\n\nПотребує 1 сокет, додає ємність у крайній правий слот інвентарю WX-78 яка автоматично готує їжу у першому слоті кожні 5 сек.\n\nЛагодження бета-модулів II покращує цей модуль: дає можливість спалити щось дерев'яне щоб отримати вугілля. Інші речі перетворяться на попіл."
STRINGS.SCRAPBOOK.SPECIALINFO.WX78MODULE_DRYER = "Підключається до плати схеми Бета WX-78. Скануйте Форморіза або Солоного Пса.\n\nПотребує 2 сокети та додає ємність для висушування у крайній правий слот інвентарю WX-78.\n\nЛагодження бета-модулів II покращує цей модуль: дає WX-78 50% водонепроникність та створює кристали солі з деяких висушених предметів."
STRINGS.SCRAPBOOK.SPECIALINFO.WX78MODULE_BREWER = "Підключається до плати схеми Гамма WX-78. Скануйте Піко, або Помаранчового Піко.\n\nПотребує 4 сокети і дає можливість WX-78 варити Пиво та робити консервації в його тілі, але це забере 50% ситості яка дорівнює показнику втамування голоду отриманого зілля.\n\nЛагодження гамма-модулів II покращує цей модуль: скорочує час заварювання та витрачену ситість на 25%."

-- Creatures.
STRINGS.SCRAPBOOK.SPECIALINFO.CHICKEN = "Їхній раціон базується на насінні, пшениці або плямистих гілочках.\n\nДикі кури мають 40% шанс знести яйце після їжі. Також є невелика ймовірність появи велетенського яйця.\n\nКури, що живуть у курнику, можуть нести яйця щодня після годування. У них значно вищий шанс знести велетенське яйце."
STRINGS.SCRAPBOOK.SPECIALINFO.PIKO = "Пухнасті маленькі друзі, які просто обожнюють красти ваші найцінніші речі!"
STRINGS.SCRAPBOOK.SPECIALINFO.KINGFISHER = "Зимородки часто випускають тропічних кої з висоти. Це буквально дощ із риби!"
STRINGS.SCRAPBOOK.SPECIALINFO.JELLYFISH_RAINBOW = "Випромінює барвисте здорове сяйво у сутінках та вночі."
STRINGS.SCRAPBOOK.SPECIALINFO.HULLBREAKER_CREATURE = "Може пошкодити корпус човна, якщо проведе успішну атаку."
STRINGS.SCRAPBOOK.SPECIALINFO.PACKIMBAGGIMS = "У Пекіма Беґґімса можна зберігати речі, як у скрині.\n\nВін обожнює їсти будь-яку рибу."
STRINGS.SCRAPBOOK.SPECIALINFO.NIGHTBIRD = "Птах, якого можна знайти тільки вночі"

-- Structures, Misc & Point of Interest.
STRINGS.SCRAPBOOK.SPECIALINFO.PIGELDER = "Торговець із далекого архіпелагу. Він охоче обміняє своє найкраще кухонне приладдя та інші корисні речі на смачні страви.\n\nСтарійшина прагне їжі з надзвичайною солодкістю або вершкового масла, змішаного з морепродуктами. Він винагородить вас належним чином.\n\nПринесення улюбленої страви Старійшини відкриє більше торгових пропозицій."
STRINGS.SCRAPBOOK.SPECIALINFO.SAMMY = "Торговець із потойбічного світу. Якимось чином він опинився на одному з островів Константи й тим часом відкрив крамницю для бартеру.\n\nСеммі торгує низкою рідкісних предметів протягом сезонів та під час особливих подій. Не забувайте час від часу перевіряти його товари.\n\nСеммі щедро винагородить вас, якщо ви принесете подарунок, що нагадає йому про дім."
STRINGS.SCRAPBOOK.SPECIALINFO.SAMMYHOUSE = "В емпоріумі Семмі зберігається безліч дивних речей та старожитностей із далеких земель і потойбічних світів."
STRINGS.SCRAPBOOK.SPECIALINFO.SAMMYWAGON = "Улюблений фургон Семмі. Нехай його розмір не вводить вас в оману — всередині можна зберігати купу речей."
STRINGS.SCRAPBOOK.SPECIALINFO.SALTPOND = "Ставки, багаті на сіль. На них можна встановити соляні стелажі, щоб кожні кілька днів отримувати кристали солі."
STRINGS.SCRAPBOOK.SPECIALINFO.MEALGRINDER = "Перебування поруч із цим пристроєм відкриє вижилому нові інгредієнти, які можна подрібнити.\n\nВам потрібно щоразу бути біля жорен, щоб подрібнити новий інгредієнт."
STRINGS.SCRAPBOOK.SPECIALINFO.PIKOTREE = "Перебування під деревом дає 35% захисту від дощу та трохи охолоджує вижилого.\n\nЦі чайні дерева кишать маленькими істотами, відомими як Піко, і вони готові створювати неприємності."
STRINGS.SCRAPBOOK.SPECIALINFO.ANTCHEST = "Ця особлива скриня може зберігати лише товари на основі меду, до 7 предметів одночасно. Вона також випромінює здорове сяйво.\n\nЯкщо всередину покласти медові страви, скриня оновить їхній термін придатності та зберігатиме їх свіжими вічно.\n\nНектар, залишений всередині, з часом перетвориться на мед."
STRINGS.SCRAPBOOK.SPECIALINFO.BREWER = "Контейнер на 3 слоти, що приймає інгредієнти для варіння напоїв.\n\nЯкщо покласти 3 предмети, розпочнеться процес варіння, що створить певний напій залежно від інгредієнтів.\n\nЦей процес зазвичай триває кілька днів."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_HANGER = "Використовується для утримання казанка."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_POT_SMALL = "Контейнер на 3 слоти для інгредієнтів.\n\nЗ 3 предметів можна приготувати страву залежно від рецепта.\n\nЦей казанок готує швидше за звичайні та має шанс видати додаткову порцію готової їжі."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_POT = "Контейнер на 4 слоти для інгредієнтів.\n\nЗ 4 предметів можна приготувати страву залежно від рецепта.\n\nЦей казанок готує швидше за звичайні та видає додаткову порцію готової їжі."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_SYRUP_POT = "Контейнер на 4 слоти для приготування сиропу.\n\nЯкщо покласти 4 одиниці соку, можна зварити сироп.\n\nЦей горщик готує лише сироп і видає 3 додаткові порції."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_OVEN = "Використовується для розміщення форми для запікання всередині."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_CASSEROLE_SMALL = "Контейнер на 3 слоти для запікання.\n\nЦя піч готує швидше за звичайні казанки та має шанс зберегти один із використаних інгредієнтів."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_CASSEROLE = "Контейнер на 4 слоти для запікання.\n\nЦя піч готує швидше за звичайні казанки та гарантовано зберігає один із використаних інгредієнтів."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_GRILL_SMALL = "Контейнер на 3 слоти для гриля.\n\nГотує швидше за звичайні казанки та видає свіжоприготовану гарячу їжу."
STRINGS.SCRAPBOOK.SPECIALINFO.COOKWARE_GRILL = "Контейнер на 4 слоти для гриля.\n\nГотує швидше за звичайні казанки та видає свіжоприготовану гарячу їжу."
STRINGS.SCRAPBOOK.SPECIALINFO.KOKONUTTREE = "Дерево дає 35% захисту від дощу та трохи охолоджує.\n\nОстерігайтеся кокосів, що падають!"
STRINGS.SCRAPBOOK.SPECIALINFO.MUSSELSTICK = "Ця палиця непереборно приваблює мідій. Залиште її на деякий час, і вона вкриється мідіями для збору."
STRINGS.SCRAPBOOK.SPECIALINFO.MUSHSTUMP = "На цьому пні росте особливий вид грибів, який багато хто вважає делікатесом.\n\nДля їхнього росту потрібно близько 5 днів."
STRINGS.SCRAPBOOK.SPECIALINFO.SUGARTREE = "Дерево дає 35% захисту від дощу та охолоджує.\n\nЗ цих дерев можна збирати сік кожні кілька днів за допомогою підсочника."
STRINGS.SCRAPBOOK.SPECIALINFO.SUGARTREE_SAPPED = "Дерево дає 35% захисту від дощу.\n\nНа виробництво соку потрібно близько 3 днів.\n\nНе дозволяйте соку переповнити відро, інакше він зіпсується."
STRINGS.SCRAPBOOK.SPECIALINFO.SUGARTREE_RUINED = "Зруйновані цукрові дерева не дають свіжого соку, натомість вони виробляють зіпсований сік.\n\nВи можете вилікувати їх за допомогою пліснявого антидоту."
STRINGS.SCRAPBOOK.SPECIALINFO.SUGARTREE_RUINED2 = "Дерево дає захист від дощу та охолоджує.\n\nВи можете вилікувати зруйновані дерева за допомогою пліснявого антидоту."
STRINGS.SCRAPBOOK.SPECIALINFO.RUBBLE = "Старійшина потребує вашої допомоги, щоб полагодити свій старий горщик і знову почати готувати смачний сироп."
STRINGS.SCRAPBOOK.SPECIALINFO.PINEAPPLEBUSH = "Ананасовим кущам потрібно майже 6 днів для повного росту. В усі пори року вони ростуть довше, окрім літа.\n\nВлітку вони починають давати врожай кожні 2 дні."
STRINGS.SCRAPBOOK.SPECIALINFO.GARDENSPRINKLER = "Можна вмикати та вимикати. Поки він заправлений паливом і ввімкнений, він автоматично поливатиме фермерські рослини в межах своєї дії."
STRINGS.SCRAPBOOK.SPECIALINFO.FARMPLOT = "Дозволяє саджати та вирощувати насіння.\n\nПосаджене насіння випадковим чином виросте в певну культуру. Конкретні рослини можна вирощувати за допомогою насіння відповідних культур.\n\nГрядки виснажуються після певної кількості врожаїв, тому їх потрібно удобрювати. Рослини, що ростуть, можна підживлювати, щоб прискорити їхній ріст.\n\nЦе підживлення впливає лише на саму рослину і не змінює стан родючості самої грядки."
STRINGS.SCRAPBOOK.SPECIALINFO.SURFACEBANANATREE = "Рідкісне та невловиме екзотичне дерево, здатне рости за межами підземного середовища.\n\nКажуть, що воно вимерло в дикій природі, і лише кілька екземплярів залишилися під наглядом фахівців."
STRINGS.SCRAPBOOK.SPECIALINFO.PARTITIO = "Гордий свин-торговець, який живе в Листяному лісі та завжди прагне виміняти свій крам на цінні речі.\n\nПопри свою пихату та суперницьку вдачу, він цінує чесних покупців і ніколи не впускає нагоди укласти вигідну угоду.\n\nОднак після деяких прикрих подій у минулому він за жодних обставин не погоджується вести справи з риболюдьми."
STRINGS.SCRAPBOOK.SPECIALINFO.PARTITIOHOUSE = "У коморі Партитіо продається безліч різноманітних товарів. Переважно це саджанці фруктових дерев та інші види рослин."
STRINGS.SCRAPBOOK.SPECIALINFO.ITEMSHOWCASER = "Споруда для демонстрації приготованих страв."
STRINGS.SCRAPBOOK.SPECIALINFO.FISHFARMPLOT = "Контейнер на 8 слотів для розведення риби.\n\nРозміщення риби в першому слоті та її годування дозволить почати розведення. Через певний час риба дасть відповідне потомство та ікру.\n\nРиба може розмножуватися лише тоді, коли виконані всі умови, адже кожна риба має свої вподобання: фаза дня, фаза місяця, сезон та локація."
STRINGS.SCRAPBOOK.SPECIALINFO.OCEANHUNT = "Бульбашковий слід, що вказує на активність у воді.\nЯкщо йти за ним, можна знайти істоту, яка його залишила."
STRINGS.SCRAPBOOK.SPECIALINFO.WHALEOCEANCARCASS = "Туша кита, яка почала псуватися.\n\nВона щодня ставатиме все більшою і більшою, поки не вибухне, вивільняючи все, що всередині.\n\nЗвук вибуху може привернути небажану увагу."
STRINGS.SCRAPBOOK.SPECIALINFO.OCTOPUSKINGTRADER = "Самотній восьминіг, що живе в безмежному океані.\n\nЯарктопус (Yaarctopus) пропонує нагороди в обмін на рибу, дрібнички та певні рибні страви з казана." 
STRINGS.SCRAPBOOK.SPECIALINFO.OCTOPUSKINGTREASURE = "Скриня Яарктопуса, яку він дарує вижилим під час обміну."
STRINGS.SCRAPBOOK.SPECIALINFO.PACKIMBAGGIMS_FISHBONE = "Прикликає Пекіма Беґґімса, якщо її підібрати.\n\nПекім Беґґімс слідуватиме за власником кістки. Поки Пекім живий, колір риби буде помаранчевим."
STRINGS.SCRAPBOOK.SPECIALINFO.HOFBIRTHDAY = "Святкуємо 5-ту річницю Heap of Foods!"
STRINGS.SCRAPBOOK.SPECIALINFO.HOFBIRTHDAY_CAKE = "Можна нарізати сікачем (Cleaver), щоб отримати шматочок ювілейного торта. Кожен шматок має свій смак та ефект.\n\nПоступово відновлює розсудок вижилим поруч.\n\nСвяткуємо 5-ту річницю Heap of Foods!"
STRINGS.SCRAPBOOK.SPECIALINFO.HOFBIRTHDAY_BALLOONS = "Поступово відновлює розсудок вижилим поруч.\n\nСвяткуємо 5-ту річницю Heap of Foods!"
STRINGS.SCRAPBOOK.SPECIALINFO.HOFBIRTHDAY_POPCORNMACHINE = "Контейнер на 2 слоти для приготування попкорну.\n\nЯкщо покласти кукурудзу в перший слот, можна отримати 5 одиниць попкорну.\n\nПід час річниці Heap of Foods машина натомість вироблятиме ювілейний попкорн.\n\nСвяткуємо 5-ту річницю Heap of Foods!"
STRINGS.SCRAPBOOK.SPECIALINFO.ANIMALFEEDER = "Деякі тварини харчуватимуться вмістом цієї годівниці.\nНасіння та зерно можна використовувати як основне джерело їжі."
STRINGS.SCRAPBOOK.SPECIALINFO.CHICKENHOUSE = "Притулок для курей, де можна отримувати птахівничу продукцію."
STRINGS.SCRAPBOOK.SPECIALINFO.DAILYRECIPE_SIGN = "Відстежує Щоденні Рецепти та дозволяє коротко ознайомитися з ними.\n\nМожна змінити на Дошку Рецептів за допомогою Пера-олівця.\n\nДошка Рецептів - декоративний варіант який дає можливість вцілілим намалювати будь-яку готову страву. Не впливає на Щоденні Рецепти."
STRINGS.SCRAPBOOK.SPECIALINFO.CAVETUBERTREE = "Потребує хорошої сокири для зрубання. Якщо не викопувати пеньок, то через декілька днів він відросте, утворюючи більшу кількість бульб.\n\nНавесні дерево починає цвісти й дозріває."